/* Tool-local adapter for the art-museum API specified in spec.md.
   The shared engine and family document do not exist in this checkout. */
const Museum = (() => {
  function frame(el, work, activate) {
    el.replaceChildren();
    el.className = 'museum-frame';
    const viewport = document.createElement('div');
    viewport.className = 'art-viewport';
    const image = document.createElement('img');
    image.src = work.img;
    image.alt = work.alt;
    image.draggable = false;
    const picture = document.createElement('button');
    picture.className = 'picture-target';
    picture.setAttribute('aria-label', 'Painting: ' + work.title + '. Tap to look closer.');
    picture.append(image);
    picture.onclick = activate || (() => zoomTo(el, {x: .5, y: .5}));
    viewport.append(picture);
    el.append(viewport);
    el.work = work;
    el.viewport = viewport;
    el.picture = picture;
    el.zoomed = false;
    const fit = () => {
      if (!image.naturalWidth || !el.isConnected) return;
      const w = el.clientWidth - 28;
      const h = el.clientHeight - 28;
      const scale = Math.min(w / image.naturalWidth, h / image.naturalHeight);
      viewport.style.width = image.naturalWidth * scale + 'px';
      viewport.style.height = image.naturalHeight * scale + 'px';
    };
    image.onload = fit;
    if (image.complete) fit();
    el.fit = fit;
    el.observer = new ResizeObserver(fit);
    el.observer.observe(el);
    return el;
  }
  function finish(el) {
    el.picture?.getAnimations().forEach(a => a.finish());
  }
  function zoomTo(el, spot) {
    finish(el);
    const x = Math.max(-140, Math.min(0, 50 - spot.x * 240));
    const y = Math.max(-140, Math.min(0, 50 - spot.y * 240));
    el.picture.style.transform = `translate(${x}%, ${y}%) scale(2.4)`;
    el.picture.style.transformOrigin = '0 0';
    el.zoomed = true;
    el.classList.add('zoomed');
    if (document.activeElement?.classList.contains('tell-pin')) el.picture.focus({preventScroll: true});
    el.querySelectorAll('.tell-pin').forEach(p => p.hidden = true);
    let ring = el.viewport.querySelector('.zoom-ring');
    if (!ring) {
      ring = document.createElement('i');
      ring.className = 'zoom-ring';
      el.viewport.append(ring);
    }
    ring.style.left = `${spot.x * 240 + x}%`;
    ring.style.top = `${spot.y * 240 + y}%`;
  }
  function unzoom(el) {
    finish(el);
    if (!el.picture) return;
    el.picture.style.transform = '';
    el.zoomed = false;
    el.classList.remove('zoomed');
    el.querySelectorAll('.tell-pin').forEach(p => p.hidden = false);
    el.viewport.querySelector('.zoom-ring')?.remove();
  }
  function pins(el, spots, opts) {
    el.querySelectorAll('.tell-pin').forEach(p => p.remove());
    for (const spot of spots) {
      const pin = document.createElement('button');
      pin.className = 'tell-pin';
      pin.style.left = `clamp(22px, ${spot.x * 100}%, calc(100% - 22px))`;
      pin.style.top = `clamp(22px, ${spot.y * 100}%, calc(100% - 22px))`;
      pin.innerHTML = opts.icon(spot.key);
      pin.setAttribute('aria-label', spot.label + ': look closer');
      pin.onclick = () => {
        opts.onPin(spot);
        zoomTo(el, spot);
      };
      el.viewport.append(pin);
    }
  }
  function label(el, work) {
    el.replaceChildren();
    const title = document.createElement('h2');
    title.textContent = work.title;
    const artist = document.createElement('p');
    artist.textContent = work.attribution;
    const detail = document.createElement('p');
    detail.textContent = `${work.date} · ${work.made}`;
    const link = document.createElement('a');
    link.href = work.url;
    link.target = '_blank';
    link.rel = 'noopener';
    link.textContent = work.museum + ' ↗';
    el.append(title, artist, detail, link);
  }
  function pair(el, workA, workB) {
    el.replaceChildren();
    for (const work of [workA, workB]) {
      const mount = document.createElement('div');
      el.append(mount);
      frame(mount, work);
    }
  }
  function dispose(root) {
    root?.querySelectorAll('.museum-frame').forEach(f => f.observer?.disconnect());
  }
  return {frame, zoomTo, unzoom, pins, label, pair, finish, dispose};
})();
